import { tags } from "typia";

/**
 * Aggregate review statistics for a product computed from customer reviews. Includes average rating (1-5 scale, null when no reviews exist), total count of active reviews, and distribution showing how many reviews exist for each star rating. Used on product detail pages to display overall product rating. Deleted reviews are excluded from all calculations.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallProductReviewStatistic = {
  /**
   * Average rating calculated from all non-deleted customer reviews for this product. Null when the product has no reviews. Value ranges from 1 to 5 stars.
   *
   * @x-autobe-specification Computed as AVG(rating) from shopping_mall_reviews where product_id matches and deleted_at IS NULL. Returns null when no non-deleted reviews exist. Value range is 1.0 to 5.0 when reviews exist.
   */
  averageRating: (number & tags.Minimum<1> & tags.Maximum<5>) | null;

  /**
   * Total number of non-deleted customer reviews for this product. Excludes soft-deleted reviews from the count.
   *
   * @x-autobe-specification Computed as COUNT(*) from shopping_mall_reviews where product_id matches and deleted_at IS NULL. Always returns integer >= 0.
   */
  totalReviewCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Breakdown of review counts by star rating (1-5 stars). Each key represents a star rating level, and the value shows how many customers gave that rating. Enables display of rating distribution histogram.
   *
   * @x-autobe-specification Computed as object with keys '1' through '5'. Each value is COUNT of reviews where rating equals that key, from shopping_mall_reviews where product_id matches and deleted_at IS NULL. Returns 0 for star ratings with no reviews.
   */
  ratingDistribution: {
    /**
     * Count of 1-star reviews.
     */
    "1": number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Count of 2-star reviews.
     */
    "2": number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Count of 3-star reviews.
     */
    "3": number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Count of 4-star reviews.
     */
    "4": number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Count of 5-star reviews.
     */
    "5": number & tags.Type<"int32"> & tags.Minimum<0>;
  };
};
